    @{ Case = 'docs';  Expected = 'documentation' }
    @{ Case = 'mixed'; Expected = 'api,backend,tests,ci,source,documentation,config' }
    @{ Case = 'none';  Expected = 'NONE' }
    @{ Case = 'tests'; Expected = 'api,backend,tests,source,documentation' }
)

